import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry } from 'three';

export default function createNode(config, ctx) {
  const group = new Group();

  // Geometry
  const geometry = new PlaneGeometry(7, 6, 64, 64);

  // Material (Node based)
  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.6;
  material.metalness = 0.2;
  material.clearcoat = 0.1;
  material.displacementScale = 0.2; // subtle depth

  // Mesh
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load textures asynchronously (function remains sync)
  const colorPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  colorPromise.then((tex) => {
    material.mapNode = texture(tex);
    material.needsUpdate = true;
  });

  depthPromise.then((tex) => {
    material.displacementNode = texture(tex);
    material.needsUpdate = true;
  });

  // Apply cinematic primitives
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const inst = ctx.primitives[p.name](group, p.params);
    primitiveInstances.push(inst);
  }

  // Event handlers
  const timelines = [];
  group.userData.handlers = {
    hover: () => {
      // rise-in: subtle upward motion 0.15 units
      const tl = gsap.timeline();
      tl.to(mesh.position, { y: mesh.position.y + 0.15, duration: 0,7, ease: 'power3.out' });
      tl.to(mesh.position, { y: mesh.position.y, duration: 0.3, ease: 'power3.in' });
      timelines.push(tl);
    },
    click: () => {
      ctx.emit('hub-home.select', {});
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose textures if they were loaded
    colorPromise.then((tex) => tex.dispose());
    depthPromise.then((tex) => tex.dispose());

    // Kill GSAP timelines
    for (const tl of timelines) tl.kill();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    }
  };

  return group;
}
